import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.DBSoX6Zw.js";const c=JSON.parse('{"title":"End-to-End Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"features/encryption.md","filePath":"features/encryption.md"}'),n={name:"features/encryption.md"};function l(p,s,h,r,k,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="end-to-end-encryption" tabindex="-1">End-to-End Encryption <a class="header-anchor" href="#end-to-end-encryption" aria-label="Permalink to &quot;End-to-End Encryption&quot;">​</a></h1><p>Plik supports optional end-to-end encryption using <a href="https://age-encryption.org/" target="_blank" rel="noreferrer">age</a>. When enabled, files are encrypted <strong>client-side</strong> before upload — the server only stores encrypted bytes and never has access to the plaintext or passphrase.</p><h2 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h2><p>Toggle <strong>End-to-End Encryption</strong> in the upload sidebar. A passphrase is auto-generated and can be customized. After upload, the passphrase is displayed in the share section with a toggle to include it in the shareable link.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # Auto-generated passphrase (default)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;passphrase&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Custom passphrase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @camathieu</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Encrypt for a GitHub user&#39;s SSH keys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitlab.com/user.keys</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # SSH keys from any URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ssh-ed25519 AAAA...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Raw SSH public key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh://myserver.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Encrypt for a server&#39;s SSH host key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> age1...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Native age X25519 recipient</span></span></code></pre></div><p>The <code>@username</code> shorthand fetches SSH keys from <code>https://github.com/{username}.keys</code>. You can also provide any URL that serves public keys (one key per line). Supported key types: <code>ssh-rsa</code>, <code>ssh-ed25519</code>, and native <code>age1…</code> X25519 recipients. The <code>ssh://hostname</code> format scans the server&#39;s SSH host key directly.</p><div class="warning custom-block"><p class="custom-block-title">Plain HTTP</p><p>Fetching keys over plain <code>http://</code> triggers a security warning — an attacker could substitute their own key (MITM). Use <code>https://</code> whenever possible. The prompt defaults to <strong>No</strong>; use <code>--yes</code> to bypass it in non-interactive scripts.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Encryption defaults can be configured in <code>~/.plikrc</code> to avoid repeating flags. Use <code>SecureOptions</code> for backend-specific settings and profiles for reusable encryption presets.</p><h3 id="setting-defaults" tabindex="-1">Setting defaults <a class="header-anchor" href="#setting-defaults" aria-label="Permalink to &quot;Setting defaults&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Always encrypt by default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Secure = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SecureMethod = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;age&quot;</span></span></code></pre></div><h3 id="encryption-profile" tabindex="-1">Encryption profile <a class="header-anchor" href="#encryption-profile" aria-label="Permalink to &quot;Encryption profile&quot;">​</a></h3><p>Create a profile to encrypt for a specific recipient:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Secure = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SecureMethod = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;age&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SecureOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Recipient = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@bob&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # github username</span></span></code></pre></div><p>Then use it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bob</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # encrypt for @bob</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plik</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> work,bob</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # use work server + encrypt for @bob</span></span></code></pre></div><p>See <a href="/plik/features/cli-client.html#secureoptions">CLI Client &gt; SecureOptions</a> for the full reference of available keys per backend.</p><h2 id="interoperability" tabindex="-1">Interoperability <a class="header-anchor" href="#interoperability" aria-label="Permalink to &quot;Interoperability&quot;">​</a></h2><p>Files encrypted via the web UI can be decrypted with the CLI and vice versa:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Decrypt a passphrase-encrypted file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file_ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decrypt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Decrypt a recipient-encrypted file (e.g. GitHub SSH key)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file_ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Decrypt a file encrypted for a server&#39;s SSH host key (requires root)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file_ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/ssh_host_ed25519_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret_file</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Use Case: Server-Only Secrets</p><p>Encrypt a file so that only a specific server can decrypt it — great for deploying secrets, config files, or credentials that only the target machine should be able to read.</p></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Upload</strong>: Files are encrypted client-side using <code>age</code> before being sent to the server</li><li><strong>Storage</strong>: The server stores only encrypted bytes and sets <code>Content-Type: application/octet-stream</code></li><li><strong>Download</strong>: The web UI prompts for the passphrase and decrypts in the browser; CLI tools receive raw encrypted bytes</li><li><strong>Passphrase</strong>: Never stored server-side — shared via the URL fragment, copy button, or out-of-band</li></ol><h2 id="feature-flag" tabindex="-1">Feature Flag <a class="header-anchor" href="#feature-flag" aria-label="Permalink to &quot;Feature Flag&quot;">​</a></h2><p>Control E2EE availability via <code>FeatureE2EE</code> in <code>plikd.cfg</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>E2EE toggle hidden in web UI</td></tr><tr><td><code>enabled</code></td><td>E2EE available, off by default (default)</td></tr><tr><td><code>default</code></td><td>E2EE available, on by default</td></tr><tr><td><code>forced</code></td><td>E2EE always on, cannot be disabled</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>E2EE is independent of server-side password protection. Password protection controls access to the upload metadata and download URLs; E2EE protects the file contents themselves.</p></div>`,28)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
